from collections import deque,defaultdict
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==6 or (r,c) in seen: continue
  col=grid[r][c]; q=[(r,c)];seen.add((r,c)); cells=[]
  while q:
   x,y=q.pop();cells.append((x,y))
   for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
    if 0<=a<R and 0<=b<C and (a,b) not in seen and grid[a][b]==col:seen.add((a,b));q.append((a,b))
  rs=[x for x,y in cells];cs=[y for x,y in cells]
  comps.append((col,len(cells),(min(rs),min(cs),max(rs),max(cs)),frozenset((x-min(rs),y-min(cs)) for x,y in cells),cells))
for i,x in enumerate(sorted(comps,key=lambda z:(-(z[2][2]-z[2][0]+1)*(z[2][3]-z[2][1]+1),-z[1]))): print(i,x[:4])

groups=defaultdict(list)
for idx,x in enumerate(comps): groups[(x[3],len(x[3]))].append((idx,x[0],x[2]))
[(k[1],v) for k,v in groups.items() if len(v)>1]
